const item = $input.first();
const b = item.json.body ?? {};
const required = ['orderId','orderCode','originalPhone','name','phone','fulfillmentMethod','deliveryDate','deliveryTimeFrom','cakeType','cakeSize'];
for (const k of required) if (b[k] === undefined || b[k] === null || String(b[k]).trim() === '') throw new Error(`Missing required field: ${k}`);
const id = Number(b.orderId);
if (!Number.isSafeInteger(id) || id <= 0) throw new Error('Invalid orderId');
const cleanPhone = v => String(v ?? '').replace(/\D/g,'').replace(/^20(?=1[0125]\d{8}$)/,'0');
if (!/^\d{11}$/.test(cleanPhone(b.originalPhone)) || cleanPhone(b.phone).length !== 11) throw new Error('Invalid phone number');
let keep;
try { keep = typeof b.imagesToKeep === 'string' ? JSON.parse(b.imagesToKeep) : (b.imagesToKeep ?? {}); } catch { throw new Error('imagesToKeep is invalid JSON'); }
if (!Array.isArray(keep.cake) || !Array.isArray(keep.deposit)) throw new Error('imagesToKeep must contain cake and deposit arrays');
let addons;
try { addons = typeof b.addOns === 'string' ? JSON.parse(b.addOns || '[]') : (b.addOns ?? []); } catch { throw new Error('addOns is invalid JSON'); }
if (!Array.isArray(addons)) throw new Error('addOns must be an array');
const numeric = ['basePriceEGP','cakeDesignExtraEGP','addOnsTotalEGP','deliveryFeeEGP','discountInputValue','discountAmountEGP','totalOrderEGP','depositEGP','remainingEGP'];
const order = {...b, addOns:addons, imagesToKeep:keep};
for (const k of numeric) { const n=Number(order[k] ?? 0); if (!Number.isFinite(n) || n < 0) throw new Error(`Invalid ${k}`); order[k]=n; }
if (order.depositEGP > order.totalOrderEGP) throw new Error('Deposit cannot exceed total order amount');
order.remainingEGP = order.totalOrderEGP - order.depositEGP;
const binary = item.binary ?? {};
const newImages = Object.keys(binary).filter(k => /^(cakeImage|depositImage)_\d+$/i.test(k));
if (keep.cake.length + newImages.filter(k=>/^cakeImage/i.test(k)).length < 1) throw new Error('لازم تحتفظ بصورة كيكة واحدة على الأقل أو ترفع صورة جديدة.');
order._newImageProperties = newImages;
return [{json:order,binary}];

const merged=$input.first();
// Merge by position combines request and SQL output; preserve webhook body and binary.
const j=merged.json;
const req=j.body ? j.body : (j.request ?? j);
const verified=j.matched !== undefined ? j : (j.verification ?? j);
if (verified.matched !== true) throw new Error('لم يتم العثور على الطلب أو بيانات التحقق غير مطابقة. لم يتم تعديل أي بيانات.');
let keep=req.imagesToKeep;
if(typeof keep==='string') keep=JSON.parse(keep);
const current=Array.isArray(verified.current_images)?verified.current_images:[];
const byId=new Map(current.map(x=>[String(x.id),x]));
const retained=[];
for(const [type,ids] of [['cake',keep.cake],['deposit',keep.deposit]]) for(const raw of ids){
 const img=byId.get(String(raw));
 if(!img || img.imageType!==type) throw new Error('تم إرسال صورة للاحتفاظ بها لا تخص هذا الطلب أو نوع الصورة غير صحيح.');
 retained.push(String(raw));
}
if(new Set(retained).size!==retained.length) throw new Error('يوجد تكرار في imagesToKeep.');
const removed=current.filter(x=>!retained.includes(String(x.id)));
const binary=merged.binary??{};
const newProps=Object.keys(binary).filter(k=>/^(cakeImage|depositImage)_\d+$/i.test(k));
const normalized={...req,orderId:Number(verified.order_id),orderCode:verified.order_code,addOns:typeof req.addOns==='string'?JSON.parse(req.addOns||'[]'):req.addOns,imagesToKeep:keep,_removedImages:removed,_newImageProperties:newProps};
return [{json:normalized,binary}];

const x=$input.first();
const j=x.json;
const req=j.body ? j.body : j;
const result=j.order_id ? j : (j.updateResult ?? j);
if(result.status!=='success') throw new Error('Order update did not complete.');
const removed=Array.isArray(result.removed_images)?result.removed_images:[];
const binary=x.binary??{};
const props=Object.keys(binary).filter(k=>/^(cakeImage|depositImage)_\d+$/i.test(k));
const actions=[];
for(const img of removed) if (img.objectKey) {
  actions.push({
    json: {
      action: 'delete',
      imageId: img.id,
      objectKey: img.objectKey,
      orderId: result.order_id
    }
  });
}
for(const prop of props){
 const b=binary[prop]; const type=/^cakeImage/i.test(prop)?'cake':'deposit';
 const safe=(b.fileName||prop+'.jpg').replace(/[^a-zA-Z0-9._-]/g,'_');
 const key=`orders/${result.order_id}/${type}/${Date.now()}_${prop}_${safe}`;
 actions.push({json:{action:'upload',orderId:result.order_id,orderCode:result.order_code,imageType:type,sourceBinaryProperty:prop,fileName:b.fileName||safe,objectKey:key,mimeType:b.mimeType||'application/octet-stream'},binary:{data:b}});
}
if(!actions.length) actions.push({json:{action:'noop',orderId:result.order_id,orderCode:result.order_code,removedCount:0,uploadedCount:0}});
return actions;

