const actions = $items('Prepare Image Actions') || [];
const first = actions[0]?.json ?? {};
const orderId = first.orderId ?? first.order_id ?? null;
const uploaded = actions.filter(x => x.json?.action === 'upload').length;
const deleted = actions.filter(x => x.json?.action === 'delete').length;
return [{json:{success:true,message:'تم تحديث الطلب ومزامنة الصور بنجاح.',orderId,uploadedImages:uploaded,deletedImages:deleted,imagesNote:'الصور التي احتفظت بها لم يتم رفعها مرة أخرى؛ تم رفع الصور الجديدة فقط.'}}];

const items = $input.all();

const messages = items.map(item => ({
  order_code: item.json.order_code,
  telegram_chat_id: item.json.telegram_chat_id,
  telegram_message_id: item.json.telegram_message_id,
  message_type: item.json.message_type
}));

return [
  {
    json: {
      messages
    }
  }
];

